import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as placeholder } from '@/primitives';
import { createText as placeholderText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 * @property {any[]} [textContent]
 * @property {any[]} [cinematicPrimitives]
 * @property {Object} [position]
 * @property {Object} [rotation]
 * @property {Object} [scale]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} tier
 */

/**
 * Creates a textured billboard plane for the Pricing card label.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // --- Geometry (aspect ratio 512 / 320 = 1.6) ---
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Material (will receive texture node later) ---
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  const plane = new Mesh(geometry, material);
  // Ensure the plane faces the camera (billboard). We'll align its normal to +Z;
  // the adapter will position it; no further rotation needed here.

  const root = new Group();
  root.add(plane);

  // Load texture and bind to material via node system
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      material.mapNode = texture(tex);
      material.needsUpdate = true;
    })
    .catch(() => {
      // Silently fail – keep plane without texture
    });

  // Store references for cleanup
  const disposables = {
    geometry,
    material,
    texturePromise,
    timelines: [] as any[],
  };

  // No cinematic primitives to apply for this node
  // (If there were, they'd be processed here per spec)

  // User data with cleanup and empty handlers container
  root.userData = {
    handlers: {},
    cleanup: () => {
      // Cancel any pending GSAP timelines
      disposables.timelines.forEach((tl) => tl.kill && tl.kill());

      // Dispose geometry and material
      disposables.geometry.dispose();
      disposables.material.dispose();

      // No explicit disposal needed for texture; the loader's cache handles it
    },
  };

  return root;
}
